"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["70271"],{94443(e){e.exports=JSON.parse('{"id":"FIN-1364","slug":"letter-of-intent","term":"Letter of Intent (LOI)","also_known_as":["LOI"],"difficulty":"Advanced","definition":"A letter of intent (LOI) is a document setting out the main terms of a proposed transaction, such as an acquisition, agreed in principle between the parties before detailed legal agreements are negotiated.","explanation":["After initial discussions and early due diligence, a buyer may submit a letter of intent to the seller. It typically covers the proposed price and how it will be paid, the structure of the deal, key conditions, the timetable, the due diligence still required and any exclusivity period.","Most terms in a letter of intent are not legally binding, allowing either side to walk away if due diligence uncovers problems or negotiations break down. However, certain clauses are usually binding, such as confidentiality and exclusivity, which prevents the seller from negotiating with other buyers for a set period.","For example, a buyer might send a letter of intent offering 60,000,000 for a business, subject to satisfactory due diligence and financing, with 60 days of exclusivity.","Letters of intent help parties confirm they agree on key points before spending heavily on lawyers and advisers. The term is often used interchangeably with term sheet, heads of terms or memorandum of understanding, though usage varies."],"note":"","total":1725,"prev":{"slug":"letter-of-credit","term":"Letter of Credit"},"next":{"slug":"leverage","term":"Leverage"}}')}}]);